  function unfc(s,into){var p="",i=0,L=s.length;while(i<L){var k=s.charCodeAt(i++)-48,j=i;while(j<L){var c=s.charCodeAt(j);if(c>=48&&c<=57)break;j++}var w=p.slice(0,k)+s.slice(i,j);into.add(w);p=w;i=j}}
